//! Password-change discovery: `/.well-known/change-password`.
//!
//! Implements the W3C Working Draft at
//! <https://www.w3.org/TR/change-password-url/>. Call before authentication
//! redirects and catch-all page routing. The destination page is the
//! application's own: it owns sign-in, reauthentication, CSRF protection and
//! the actual password change. Upstream Ferrite Core has no platform password
//! store, so an application that serves no such page leaves the destination
//! unset and discovery answers 404.
//!
//! With agent-ready, name the page through `PageSource::change_password_url`
//! and route through `agent_ready::well_known::handle_h`, emitting every
//! header it returns. See packages/http-change-password/README.md.

/// The origin-root discovery path, independent of the app's auth prefix.
pub const PATH: &str = "/.well-known/change-password";

/// Guidance carried by generated app skills and the MCP initialize response.
/// Discovery is deliberately not a credential-handling MCP operation.
pub const AGENT_GUIDANCE: &str = "For password changes, open /.well-known/change-password in the browser; 404 means this app does not advertise a password-change flow. The user enters credentials in the browser. Never collect passwords in MCP arguments, agent context, logs, or application queues. Discovery does not authorize a change.";

