#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn get_and_head_redirect_without_forwarding_request_parameters() {
        let target = "/account/password?section=security&mode=change";
        let get = handle(
            "GET",
            &format!("{PATH}?next=https://evil.example"),
            Some(target),
        )
        .unwrap();
        let head = handle("HEAD", PATH, Some(target)).unwrap();
        assert_eq!(get.status, 303);
        assert_eq!(get.headers, head.headers);
        assert!(get.headers.contains(&("location", target.into())));
        assert!(get.headers.contains(&("cache-control", "no-store".into())));
        let body = String::from_utf8(get.body).unwrap();
        assert!(body.contains("&amp;mode=change"));
        assert!(!body.contains("evil.example"));
        assert!(head.body.is_empty());
    }

    #[test]
    fn disabled_discovery_is_a_real_404_and_other_paths_fall_through() {
        for method in ["GET", "HEAD", "POST"] {
            let response = handle(method, PATH, None).unwrap();
            assert_eq!(response.status, 404);
            assert!(!response.headers.iter().any(|(name, _)| *name == "location"));
        }
        for path in [
            "/",
            "/account/password",
            "/.well-known/missing",
            "/.well-known/change-password/extra",
        ] {
            assert!(handle("GET", path, Some("/account/password")).is_none());
        }
    }

    #[test]
    fn unsafe_methods_never_redirect_or_forward_a_body() {
        for method in ["POST", "PUT", "PATCH", "DELETE", "OPTIONS"] {
            let response = handle(method, PATH, Some("/account/password")).unwrap();
            assert_eq!(response.status, 405);
            assert!(response.headers.contains(&("allow", "GET, HEAD".into())));
            assert!(!response.headers.iter().any(|(name, _)| *name == "location"));
            assert!(response.body.is_empty());
        }
    }

    #[test]
    fn rejects_open_redirects_header_injection_and_discovery_loops() {
        for target in [
            "",
            "account/password",
            "https://example.com/password",
            "//evil.example",
            "/\\evil.example",
            "/password\r\nLocation: https://evil.example",
            "/a b",
            "/%2f%2fevil.example",
            "/%252f%252fevil.example",
            "/a/../.well-known/change-password",
            "/./.well-known/change-password",
            "/.well-known//change-password",
            PATH,
            "/.well-known/change-password?again=1",
            "/.well-known/change-password#again",
            "/.well-known/change-password/",
            "/password\" onload=\"bad",
            "/password'",
            "/password<bad>",
        ] {
            assert!(!valid_destination(target), "accepted {target:?}");
            let response = handle("GET", PATH, Some(target)).unwrap();
            assert_eq!(response.status, 500, "{target:?}");
            assert!(response.body.is_empty());
            assert_eq!(response.headers, vec![("cache-control", "no-store".into())]);
        }
    }
}
